curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&types=public_channel&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        print(ch['id'], ch['name'])
else:
    print('Error:', data.get('error'))
"

curl -s -X POST "https://slack.com/api/conversations.history" -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&channel=C_INC&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data['messages']:
        reactions = msg.get('reactions', [])
        if reactions:
            print(f'--- Message ts={msg[\"ts\"]} by {msg[\"user\"]}: {msg.get(\"text\",\"\")[:80]}')
            for r in reactions:
                print(f'    reaction: {r[\"name\"]} by {r[\"users\"]}')
else:
    print('Error:', data.get('error'))
"

curl -s -X POST "https://slack.com/api/conversations.history" -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&channel=C_INC&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    msgs = data['messages']
    print(f'Total messages: {len(msgs)}')
    for msg in msgs:
        print(f'ts={msg[\"ts\"]} user={msg[\"user\"]} text={msg.get(\"text\",\"\")[:80]}')
        if 'reactions' in msg:
            print(f'  reactions: {json.dumps(msg[\"reactions\"])}')
else:
    print('Error:', data.get('error'))
"

